#[inline]
pub fn png_do_write_interlace(
    mut row_info: png_row_infop,
    mut row: png_bytep,
    mut pass: c_int,
) {
    unsafe {
        static mut png_pass_start: [png_byte; 7] = [
            0 as c_int as png_byte,
            4 as c_int as png_byte,
            0 as c_int as png_byte,
            2 as c_int as png_byte,
            0 as c_int as png_byte,
            1 as c_int as png_byte,
            0 as c_int as png_byte,
        ];
        static mut png_pass_inc: [png_byte; 7] = [
            8 as c_int as png_byte,
            8 as c_int as png_byte,
            4 as c_int as png_byte,
            4 as c_int as png_byte,
            2 as c_int as png_byte,
            2 as c_int as png_byte,
            1 as c_int as png_byte,
        ];

        if pass < 6 as c_int {
            let width = (*row_info).width;
            let pixel_depth = (*row_info).pixel_depth;
            let pass_idx = pass as usize;
            let pass_start = png_pass_start[pass_idx] as png_uint_32;
            let pass_inc = png_pass_inc[pass_idx] as png_uint_32;

            match pixel_depth as c_int {
                1 => {
                    let mut shift: c_uint = 7 as c_uint;
                    let mut d: c_int = 0 as c_int;
                    let mut out_byte: png_size_t = 0;
                    let mut i = pass_start;
                    while i < width {
                        let src_byte_index = (i >> 3 as c_int) as png_size_t;
                        let value = *row.offset(src_byte_index as isize) as c_int
                            >> (7 as c_int - (i as c_uint & 0x7 as c_uint) as c_int)
                            & 0x1 as c_int;
                        d |= value << shift;
                        if shift == 0 as c_uint {
                            *row.offset(out_byte as isize) = d as png_byte;
                            out_byte = out_byte.wrapping_add(1);
                            shift = 7 as c_uint;
                            d = 0 as c_int;
                        } else {
                            shift = shift.wrapping_sub(1);
                        }
                        i = i.wrapping_add(pass_inc);
                    }
                    if shift != 7 as c_uint {
                        *row.offset(out_byte as isize) = d as png_byte;
                    }
                }
                2 => {
                    let mut shift: c_uint = 6 as c_uint;
                    let mut d: c_int = 0 as c_int;
                    let mut out_byte: png_size_t = 0;
                    let mut i = pass_start;
                    while i < width {
                        let src_byte_index = (i >> 2 as c_int) as png_size_t;
                        let value = *row.offset(src_byte_index as isize) as c_int
                            >> ((3 as c_int - (i as c_uint & 0x3 as c_uint) as c_int)
                                << 1 as c_int)
                            & 0x3 as c_int;
                        d |= value << shift;
                        if shift == 0 as c_uint {
                            *row.offset(out_byte as isize) = d as png_byte;
                            out_byte = out_byte.wrapping_add(1);
                            shift = 6 as c_uint;
                            d = 0 as c_int;
                        } else {
                            shift = shift.wrapping_sub(2 as c_uint);
                        }
                        i = i.wrapping_add(pass_inc);
                    }
                    if shift != 6 as c_uint {
                        *row.offset(out_byte as isize) = d as png_byte;
                    }
                }
                4 => {
                    let mut shift: c_uint = 4 as c_uint;
                    let mut d: c_int = 0 as c_int;
                    let mut out_byte: png_size_t = 0;
                    let mut i = pass_start;
                    while i < width {
                        let src_byte_index = (i >> 1 as c_int) as png_size_t;
                        let value = *row.offset(src_byte_index as isize) as c_int
                            >> ((1 as c_int - (i as c_uint & 0x1 as c_uint) as c_int)
                                << 2 as c_int)
                            & 0xf as c_int;
                        d |= value << shift;
                        if shift == 0 as c_uint {
                            *row.offset(out_byte as isize) = d as png_byte;
                            out_byte = out_byte.wrapping_add(1);
                            shift = 4 as c_uint;
                            d = 0 as c_int;
                        } else {
                            shift = shift.wrapping_sub(4 as c_uint);
                        }
                        i = i.wrapping_add(pass_inc);
                    }
                    if shift != 4 as c_uint {
                        *row.offset(out_byte as isize) = d as png_byte;
                    }
                }
                _ => {
                    let pixel_bytes =
                        ((pixel_depth as c_int) >> 3 as c_int) as png_size_t;
                    let mut out_byte: png_size_t = 0;
                    let mut i = pass_start;
                    while i < width {
                        let src_offset =
                            (i as png_size_t).wrapping_mul(pixel_bytes);
                        let dst = row.offset(out_byte as isize);
                        let src = row.offset(src_offset as isize);
                        if dst != src {
                            // SAFETY: `dst` and `src` are derived from the same valid row buffer,
                            // both are valid for `pixel_bytes` bytes by the original function's
                            // unchecked pointer semantics, and this branch preserves the original
                            // non-overlap precondition required by memcpy/copy_nonoverlapping via
                            // the existing `dst != src` fast-path structure used here.
                            core::ptr::copy_nonoverlapping(src, dst, pixel_bytes);
                        }
                        out_byte = out_byte.wrapping_add(pixel_bytes);
                        i = i.wrapping_add(pass_inc);
                    }
                }
            }

            let new_width = (width as c_uint)
                .wrapping_add(pass_inc as c_uint)
                .wrapping_sub(1 as c_uint)
                .wrapping_sub(pass_start as c_uint)
                .wrapping_div(pass_inc as c_uint) as png_uint_32;
            (*row_info).width = new_width;
            (*row_info).rowbytes = if pixel_depth as c_int >= 8 as c_int {
                (new_width as png_size_t)
                    .wrapping_mul(pixel_depth as png_size_t >> 3 as c_int)
            } else {
                (new_width as png_size_t)
                    .wrapping_mul(pixel_depth as png_size_t)
                    .wrapping_add(7 as png_size_t)
                    >> 3 as c_int
            };
        }
    }
}

